@icontract.require(lambda arr: all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1)))
@icontract.ensure(lambda arr, elem, result: result < 0 or (result < len(arr) and arr[result] == elem and all(x != elem for x in arr[result + 1:])))
@icontract.ensure(lambda arr, elem, result: result != -1 or all(x != elem for x in arr))
def lastPosition(arr: List[int], elem: int) -> int:
    i = len(arr) - 1
    while i >= 0:
        if arr[i] == elem:
            return i
        i -= 1
    return -1
